const sv = (k, v) => { svLocal(k, v); if (!LOCAL_ONLY.has(k) && PREFS) PREFS.set(k, v); };
const DK = () => { const d = new Date(); return d.getFullYear() + "-" + String(d.getMonth() + 1).padStart(2, "0") + "-" + String(d.getDate()).padStart(2, "0"); };
const T = { bg: "var(--bg)", card: "var(--card)", bdr: "var(--line)", blue: "var(--accent)", green: "var(--ok)", red: "var(--danger)", orange: "var(--accent)", purple: "var(--accent2)" };
