  btn: (bg = T.blue, c = "#fff") => ({ background: bg, color: c, border: "none", borderRadius: 10, padding: "11px 0", fontSize: 14, fontWeight: 700, fontFamily: "'Cairo',sans-serif", cursor: "pointer", width: "100%", marginTop: 4 }),
  div: { height: 1, background: T.bdr, margin: "8px 0" },
