const VAPID_PUBLIC_KEY = "BKNEkbQpChTjFNE1iGLE5Cj0ZCp8LmainE1U0eQD4lXwDPiUQFNZfZmk93DIZv30EDVBbCwtq8o5Zaz5YBEa74A";
const PRAYER_NAMES = { Fajr: "الفجر", Dhuhr: "الظهر", Asr: "العصر", Maghrib: "المغرب", Isha: "العشاء" };
function urlB64ToU8(b64) { const pad = "=".repeat((4 - (b64.length % 4)) % 4); const raw = atob((b64 + pad).replace(/-/g, "+").replace(/_/g, "/")); const o = new Uint8Array(raw.length); for (let i = 0; i < raw.length; ++i) o[i] = raw.charCodeAt(i); return o; }
async function notifyNow(title, body, tag, go) {
  const o = { body: body || "", tag: tag || "allinone-local", renotify: true, data: { go: go || "none", url: "./" } };
  try { const reg = "serviceWorker" in navigator ? await navigator.serviceWorker.getRegistration() : null; if (reg && reg.showNotification) return reg.showNotification(title, o); } catch (e) {}
  try { new Notification(title, { body: o.body }); } catch (e) {}
}
// ── مفتاح VAPID: بنجيبه من الـ Worker نفسه عشان يطابق مفتاحه الخاص، ولو مش متاح بنستخدم المدمج
const PUSH_WORKER_URL = "https://prayer-push-worker.mohamedhossamomara01.workers.dev";
async function getPushKey() {
  try { const ctl = new AbortController(); const t = setTimeout(() => ctl.abort(), 6000); const r = await fetch(PUSH_WORKER_URL + "/?key=1", { signal: ctl.signal }); clearTimeout(t); const j = await r.json(); if (j && j.key && String(j.key).length > 60) return String(j.key).trim(); } catch (e) {}
  return "BIG2vA6-oPQMpi224vbWJNVyulpQL6Zkk3AseaFZ0OoGG8rjQOVkJkmqPe1fiZshk1pW04_OpYkDz0iUvXLBI50";
}
async function ensurePushSub(reg, create) {
  const want = urlB64ToU8(await getPushKey());
  let sub = await reg.pushManager.getSubscription();
  if (sub) { const have = sub.options && sub.options.applicationServerKey ? new Uint8Array(sub.options.applicationServerKey) : null; const same = have && have.length === want.length && have.every((b, i) => b === want[i]); if (!same) { try { await sub.unsubscribe(); } catch (e) {} sub = null; } }
  if (!sub && create) sub = await reg.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey: want });
  return sub;
}
async function subscribePush(lat, lon) {
  if (!("serviceWorker" in navigator) || !("PushManager" in window)) return { ok: false, reason: "الموبايل ده مش بيدعم Push Notifications" };
  let reg = await navigator.serviceWorker.getRegistration();
  if (!reg) reg = await navigator.serviceWorker.register("./sw.js");
  await navigator.serviceWorker.ready;
  const sub = await ensurePushSub(reg, true);
  const j = sub.toJSON();
  if (SB) await SB.from("push_subscriptions").upsert({ endpoint: j.endpoint, p256dh: j.keys.p256dh, auth: j.keys.auth, latitude: lat, longitude: lon, settings: buildPushSettings(), updated_at: new Date().toISOString() }, { onConflict: "endpoint" });
  return { ok: true };
}
