const TAFSIR_EDITIONS = [["ar-tafsir-ibn-kathir", "ابن كثير"], ["ar-tafsir-as-saadi", "السعدي"], ["ar-tafsir-muyassar", "الميسّر"], ["ar-tafsir-al-jalalayn", "الجلالين"], ["ar-tafseer-al-qurtubi", "القرطبي"], ["ar-tafsir-al-tabari", "الطبري"]];
